head.script:
// https://inswave01.atlassian.net/browse/WAEA-686



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnBackgroundColor]<br/>Column 정보를 사용하여 특정 Column 의 배경색을 반환합니다.",
    "validation" : [
        "colInfo(필수) 파라미터로 배경색을 조회할 특정 Column 의 Column ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    $c.gcm.createBasicGridView(cList);

    // 두번째 Column 숨김 처리
    target1.setColumnVisible("col2", false);

    // 각 Row 에 배경색 설정
    for (var i=0; i<4; i++)
        target1.setRowBackgroundColor(i, "lightyellow");

    // 일부 Column 에 배경색 설정
    target1.setColumnBackgroundColor("col1", "red");
    target1.setColumnBackgroundColor("col3", "blue");
}



scwin.btn_getColumnBackgroundColor_onclick = function () {
    let colInfo = par_colInfo.getText();

    let rtn = target1.getColumnBackgroundColor(colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnBackgroundColor(" + colInfo + ") : " + rtn);

    // 반환값이 빈 문자열인 경우 실제 Cell 의 style.backgroundColor 확인
    if (rtn === '') {
        let colIndex = target1.getColumnIndex(colInfo);
        let cellEl = document.querySelector("td[id*='target1_cell_0_" + colIndex + "']");
        wf_body_bottom.getObj("scwin").setReturnValue("style.backgroundColor : " + cellEl.style.backgroundColor);
    }
}
